#!/usr/bin/env python3
"""v2-29: New screens, Stage A (Today hero with one next step, line icons). Run from the nutrismart project folder. Safe to run twice.
OFF until you switch on 'ui_screens_a'."""
import base64, os, sys
if not os.path.isdir('src') or not os.path.isdir('functions'):
    sys.exit('Run this inside the nutrismart project folder (cd ~/Downloads/nutrismart).')
def rd(p): return open(p, encoding='utf8').read()
def wr(p, s):
    os.makedirs(os.path.dirname(p) or '.', exist_ok=True); open(p, 'w', encoding='utf8').write(s)
def sub(p, old, new, marker):
    s = rd(p)
    if marker in s: print('already applied:', p); return
    if old not in s: sys.exit(f'Cannot find the expected text in {p}. Stop and send this message to Claude.')
    wr(p, s.replace(old, new, 1)); print('updated', p)
def append(p, text, marker):
    s = rd(p)
    if marker in s: print('already applied:', p); return
    wr(p, s.rstrip('\n') + '\n' + text); print('updated', p)
NEW = {
  'src/components/screens/TodayHero.tsx': '',
  'src/components/screens/NavIcon.tsx': '',
  'src/styles/newdesign.css': '',
  'src/tests/ui29/screensA.test.ts': '',
  'src/lib/todayAction.ts': '',
  'supabase/migrations/048_ui_screens_a.sql': '',
  'docs/NEW_SCREENS_A.md': '',
}
if not os.path.exists('src/styles/newdesign.css'): sys.exit('Run v2-26, v2-27 and v2-28 first.')
for p, b in NEW.items():
    wr(p, base64.b64decode(b).decode('utf8')); print('wrote', p)

sub('src/pages/tabs/TodayTab.tsx', "import { WelcomeBackCard } from '../../components/delight/WelcomeBackCard';", "import { WelcomeBackCard } from '../../components/delight/WelcomeBackCard';\nimport { TodayHero } from '../../components/screens/TodayHero';", "import { TodayHero }")
sub('src/pages/tabs/TodayTab.tsx', "  const welcomeOn = useFlag('ui_welcome_back');", "  const welcomeOn = useFlag('ui_welcome_back');\n  const heroOn = useFlag('ui_screens_a');", "useFlag('ui_screens_a')")
sub('src/pages/tabs/TodayTab.tsx', "      {welcomeOn && <WelcomeBackCard />}", "      {welcomeOn && <WelcomeBackCard />}\n\n      {heroOn && <TodayHero sectors={plate} meals={summary.meals} hourIST={hourIST} />}", "{heroOn && <TodayHero")
sub('src/pages/tabs/TodayTab.tsx', "      {plateOn && (\n        <PlateCard", "      {plateOn && !heroOn && (\n        <PlateCard", "{plateOn && !heroOn && (")

sub('src/pages/AppShell.tsx', "import { ThemeHost } from '../components/theme/ThemeHost';", "import { ThemeHost } from '../components/theme/ThemeHost';\nimport { NavIcon } from '../components/screens/NavIcon';\nimport { useFlag } from '../lib/useFlag';", "import { NavIcon }")
sub('src/pages/AppShell.tsx', "  const isRefreshing = useIsRefreshing();", "  const isRefreshing = useIsRefreshing();\n  const iconsOn = useFlag('ui_screens_a');", "useFlag('ui_screens_a')")
sub('src/pages/AppShell.tsx', '<span className="text-base">{tab.icon}</span>', '<span className="text-base">{iconsOn ? <NavIcon name={tab.label} size={20} /> : tab.icon}</span>', "size={20}")
sub('src/pages/AppShell.tsx', '<span className="text-[22px] leading-none">{tab.icon}</span>', '<span className="text-[22px] leading-none">{iconsOn ? <NavIcon name={tab.label} /> : tab.icon}</span>', "iconsOn ? <NavIcon name={tab.label} />")

s = rd('src/tests/v2/BlueprintContract.test.ts')
for old in ('46', '47'):
    if f'says {old} migrations' in s:
        wr('src/tests/v2/BlueprintContract.test.ts', s.replace(f'says {old} migrations', 'says 48 migrations').replace(f'expect(n).toBe({old})', 'expect(n).toBe(48)')); print('updated BlueprintContract'); break
append('docs/PROGRESS.md', "\n## New screens, Stage A (migration 048)\nToday hero (thali + one next step) and line icons, behind ui_screens_a (off by default). See docs/NEW_SCREENS_A.md.\n", 'New screens, Stage A')
print('\nDone. Next: run supabase/migrations/048_ui_screens_a.sql in Supabase, then commit and push.')
